/** Stop this caller's wait without cancelling a promise shared with other callers. */ export async function awaitWithSignal(promise, signal) {
    let onAbort;
    const cancellation = new Promise((_resolve, reject)=>{
        onAbort = ()=>{
            const reason = signal.reason;
            reject(reason instanceof Error ? reason : new DOMException('The operation was aborted', 'AbortError'));
        };
        if (signal.aborted) {
            onAbort();
        } else {
            signal.addEventListener('abort', onAbort, {
                once: true
            });
        }
    });
    try {
        // Observe the shared promise even if cancellation has already occurred.
        return await Promise.race([
            cancellation,
            promise
        ]);
    } finally{
        if (onAbort) {
            signal.removeEventListener('abort', onAbort);
        }
    }
}
